script.text:

function init$&Identity;Filter$(f) {}
function active$&Identity;Filter$(f) {
  var g = f.grid, w = null;
  try {w = g.get_element() && g.get_element().parentForm;} catch (ex) {}
  if (!w || w === f) w = document.body._form;
  if (w === f) w = null;

  // Gom khóa các dòng grid cha đã tick (cột {{tag_field}}, khóa {{key_field}}) vào field keys
  var a = [];
  if (g && g._rowCount) {
    var t = g._getColumnOrder('{{tag_field}}'), k = g._getColumnOrder('{{key_field}}');
    for (var r = 1; r <= g._rowCount; r++) {
      if (t > -1 && g._getItemValue(r, t)) a.push($func.trim(String(g._getItemValue(r, k) || '')));
    }
  }
  f.setItemValue('keys', a.join(','));

  // GIỮ memvars của grid ngoài cùng: khóa _memvars trong lúc popup mở
  if (g) {
    if (!g._isPopupFilterActive && g._memvars) {
      g._originMemvars = g._memvars;
    }
    g._isPopupFilterActive = true;
    try {
      Object.defineProperty(g, '_memvars', {
        get: function() { return g._originMemvars; },
        set: function(val) {
          if (!g._isPopupFilterActive && val) {
            g._originMemvars = val;
          }
        },
        configurable: true,
        enumerable: true
      });
    } catch (ex) {}
  }
}
function close$&Identity;Filter$(f) {
  var g = f.grid;
  if (g && g._originMemvars) {
    try { g._memvars = g._originMemvars; } catch (ex) {}
    setTimeout(function() { g._isPopupFilterActive = false; }, 300);
  }
}
function on$&Identity;Filter$QueryComplete(f, name_date_1, name_lookup_1, name_decimal_1, name_string_1) {
  var g = f.grid, w = (g && g.get_element() && g.get_element().parentForm) || document.body._form;
  // AGENT: chọn 1 trong 2 cách gán ngược, xóa cách không dùng
  // (a1) gán vào field header của form cha
  if (w) {
    w.setItemValues('{{dest_fields}}', [name_lookup_1, name_decimal_1]);
  }
  // (a2) gán vào các dòng grid cha đã tick
  if (g && g._rowCount) {
    var t = g._getColumnOrder('{{tag_field}}'), c = g._getColumnOrder('{{dest_grid_field}}');
    for (var r = 1; r <= g._rowCount; r++) {
      if (t > -1 && c > -1 && g._getItemValue(r, t)) g._setItemValue(r, c, name_decimal_1);
    }
  }
  if (g) {
    if (!g._formScript) g._formScript = ' ';
    if (g._originMemvars) {
      try { g._memvars = g._originMemvars; } catch (ex) {}
    }
  }
}
